public interface UserDaoFactory { String store(); UserDao userDao(); }

ServiceLoader<UserDaoFactory> factories = ServiceLoader.load(UserDaoFactory.class);

UserDao users = factories.stream()
        .map(ServiceLoader.Provider::get)
        .filter(f -> f.store().equals(configuredStore))
        .findFirst()
        .orElseThrow(() -> new IllegalStateException("no DAO factory for " + configuredStore))
        .userDao();

public abstract class DAOFactory {
    public abstract UserDao userDao();
    public abstract OrderDao orderDao();

    public static DAOFactory getDAOFactory(Store which) {
        return switch (which) {
            case POSTGRES -> new PgDAOFactory(pgDataSource());
            case SQLITE   -> new SqliteDAOFactory(sqliteDataSource());
        };
    }
}
